# Set up logging
logging.basicConfig(level=logging.INFO, filename='runtime.log', filemode='a', format='%(message)s')

# Redirect stdout and stderr to the log file
class StreamToLogger(object):
    def __init__(self, logger, log_level=logging.INFO):
        self.logger = logger
        self.log_level = log_level
        self.linebuf = ''
    
    def write(self, buf):
        for line in buf.rstrip().splitlines():
            self.logger.log(self.log_level, line.rstrip())
    
    def flush(self):
        pass

sys.stdout = StreamToLogger(logging.getLogger('STDOUT'), logging.INFO)
sys.stderr = StreamToLogger(logging.getLogger('STDERR'), logging.ERROR)

# Redirect warnings to logging
def custom_warning_handler(message, category, filename, lineno, file=None, line=None):
    logging.warning(f'{filename}:{lineno}: {category.__name__}: {message}')

warnings.showwarning = custom_warning_handler


def remove_by(lst, idx):
	for index in idx:
		del lst[index]

	return lst

def ErrorCorrection(in_inverse, FinalBestPossibleCoeff, allEncryptedParamsOfInverse, K):
    _r = lambda y: np.round(y, decimals=64)
    y_estimated = FinalBestPossibleCoeff[0]

    # Create a copy of the coefficients to avoid modifying the original
    adjusted_coeffs = FinalBestPossibleCoeff.copy()

    for i in range(1, len(adjusted_coeffs)):
        adjusted_coeffs[i] /= K**(i-1)


    for j in range(1, len(adjusted_coeffs)):

        try:
            value_iter = allEncryptedParamsOfInverse[j-1] * adjusted_coeffs[j]

            HE.rescale_to_next(value_iter)
            ~value_iter

            y_estimated = y_estimated + (value_iter)
        
        except Exception as e:
            # print('exception...', e)
            break

    return y_estimated


def getEncryptedValues(EN_x, in_Constant_K):

    _r = lambda y: np.round(y, decimals=64)

    Constant_K = in_Constant_K

    # HE.rescale_to_next(EN_x)

    #kX
    En_x_k = Constant_K * EN_x
    HE.rescale_to_next(En_x_k)
    ~En_x_k

    #k2X2
    EN_x2_k2 = En_x_k ** 2
    HE.rescale_to_next(EN_x2_k2)
    ~EN_x2_k2

    #k4X4
    EN_x4k4 = EN_x2_k2 ** 2
    HE.rescale_to_next(EN_x4k4)
    ~EN_x4k4

    #k8X8
    EN_x8k8 = EN_x4k4 ** 2
    HE.rescale_to_next(EN_x8k8)
    ~EN_x8k8

    #k16X16
    EN_x16k16 = EN_x8k8 ** 2
    HE.rescale_to_next(EN_x16k16)
    ~EN_x16k16


    #X2 = x * x

    EN_x_2_1 = (EN_x ** 2)
    HE.rescale_to_next(EN_x_2_1)
    ~EN_x_2_1

    #kX2 = x * kx

    EN_x_2 =  EN_x * En_x_k
    HE.rescale_to_next(EN_x_2)
    ~EN_x_2

    #k2X3 = x * k2x2

    EN_x_3 = EN_x * EN_x2_k2
    HE.rescale_to_next(EN_x_3)
    ~EN_x_3

    #k3X4 = (X * KX) * K2X2

    EN_x_4 = EN_x_2 * EN_x2_k2
    HE.rescale_to_next(EN_x_4)
    ~EN_x_4

	#k4X5 = x * k4x4

    EN_x_5 = EN_x * EN_x4k4
    HE.rescale_to_next(EN_x_5)
    ~EN_x_5

