    sample_size = 1000
    scaling_factor = numconsumers / sample_size

    t_totalPrice = sum(in_consumerPrices[:sample_size]) * scaling_factor

    # t_ChangedPrice = []

    constant = 2 * ETA / (in_sDotLambdaZero - in_wDotLambdaZero)

    # print("Constant Consumer: ", constant)

    ratio = in_supply/t_totalPrice

    ValueTerm = (1.0 - (constant * ratio))

