def computeSupplierPricingSingalfloat(in_consumerPrices, in_demand, in_sDotLambdaZero, in_supply, in_wDotLambdaZero):
    out_consumerPrices = []

    t_totalPrice = sum(in_consumerPrices)

    t_ChangedPrice = []

    constant = 2 * ETA / (in_sDotLambdaZero - in_wDotLambdaZero)

    # print("Constant Supplier: ", constant)

    # for i in range(len(in_consumerPrices)):
    # 	div_value = in_consumerPrices[i]/t_totalPrice
    # 	firstTerm = in_supply * div_value
    # 	gse = in_demand[i] - firstTerm
    # 	ChangeInPrice = gse * constant
    # 	t_ChangedPrice.append(ChangeInPrice)

    ratio = in_supply/t_totalPrice

    ValueTerm = (1.0 + (constant * ratio))

    for i in range(len(in_consumerPrices)):
    	Price = (in_consumerPrices[i] * ValueTerm) - (constant * in_demand[i])
    	out_consumerPrices.append(Price)

    return out_consumerPrices


